<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$db=$GLOBALS['pdo'];$rows=$db->query('SELECT w.plan,COUNT(DISTINCT w.id) workspaces,COUNT(DISTINCT d.id) datasets,COALESCE(SUM(d.storage_bytes),0) storage_bytes,COALESCE(SUM(u.units),0) ai_queries FROM workspaces w LEFT JOIN datasets d ON d.workspace_id=w.id LEFT JOIN usage_logs u ON u.workspace_id=w.id AND u.usage_type="ai_query" AND u.month_key=DATE_FORMAT(CURDATE(),"%Y-%m") GROUP BY w.plan ORDER BY FIELD(w.plan,"free","pro","business")')->fetchAll();$months=[];for($i=5;$i>=0;$i--){$d=(new DateTimeImmutable('first day of this month'))->modify('-'.$i.' months');$months[$d->format('Y-m')]=['label'=>$d->format('M y'),'queries'=>0,'uploads'=>0,'exports'=>0];}$st=$db->query('SELECT month_key,usage_type,SUM(units) units FROM usage_logs WHERE month_key>=DATE_FORMAT(DATE_SUB(CURDATE(),INTERVAL 5 MONTH),"%Y-%m") GROUP BY month_key,usage_type');foreach($st->fetchAll() as $item)if(isset($months[$item['month_key']]))$months[$item['month_key']][['ai_query'=>'queries','dataset_upload'=>'uploads','export'=>'exports'][$item['usage_type']]]=(int)$item['units'];$series=array_values($months);$st=$db->query('SELECT usage_type,COUNT(*) rows_logged,COALESCE(SUM(units),0) units FROM usage_logs GROUP BY usage_type');$all=$st->fetchAll();$st=$db->query('SELECT COALESCE(SUM(storage_bytes),0) bytes,COUNT(*) files FROM datasets');$storage=$st->fetch();require_once __DIR__.'/../includes/header.php';$layout='admin';datanix_header('Usage and storage','usage',$layout);
?>
<div class="admin-kicker">METERING &amp; INFRASTRUCTURE</div><h1 class="admin-page-title">Usage &amp; storage</h1><p class="admin-page-desc">Data berasal dari usage log, dataset metadata, dan hitungan saat ini. Nilai menunjukkan pemakaian yang benar-benar tercatat.</p>
<div class="admin-grid mb-3"><article class="admin-stat"><small>AI queries · bulan ini</small><strong><?=e(format_number((int)array_sum(array_column($series,'queries'))))?></strong><span>Jumlah usage_logs</span></article><article class="admin-stat"><small>Dataset files tracked</small><strong><?=e(format_number((int)$storage['files']))?></strong><span>Upload dan source metadata</span></article><article class="admin-stat"><small>Storage size</small><strong><?=e(format_number((int)$storage['bytes']/1048576,2))?> MB</strong><span>Ukuran upload yang tercatat</span></article><article class="admin-stat"><small>Workspaces</small><strong><?=e(format_number((int)$db->query('SELECT COUNT(*) FROM workspaces')->fetchColumn()))?></strong><span>Semua paket</span></article></div>
<div class="row g-3"><div class="col-lg-8"><section class="admin-card"><div class="admin-card-head"><strong>Usage by month and type</strong><span class="admin-badge">Actual usage</span></div><div class="admin-card-body"><div class="chart-canvas" data-chart="<?=e(json_encode(['labels'=>array_column($series,'label'),'values'=>array_column($series,'queries'),'type'=>'line'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT))?>"></div><div class="source-attribution">The chart displays AI query units. Upload and export totals are listed separately from recorded logs below.</div></div></section></div><div class="col-lg-4"><section class="admin-card"><div class="admin-card-head"><strong>Current usage by plan</strong></div><table class="admin-table"><thead><tr><th>Plan</th><th>Workspace</th><th>Datasets</th><th>Queries</th><th>MB</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e(strtoupper($row['plan']))?></td><td><?=e($row['workspaces'])?></td><td><?=e($row['datasets'])?></td><td><?=e($row['ai_queries'])?></td><td><?=e(format_number((int)$row['storage_bytes']/1048576,2))?></td></tr><?php endforeach;?></tbody></table></section></div></div>
<section class="admin-card mt-3"><div class="admin-card-head"><strong>Recorded usage logs by type</strong></div><table class="admin-table"><thead><tr><th>Usage type</th><th>Log rows</th><th>Units</th></tr></thead><tbody><?php foreach($all as $item):?><tr><td><?=e($item['usage_type'])?></td><td><?=e(format_number((int)$item['rows_logged']))?></td><td><?=e(format_number((int)$item['units']))?></td></tr><?php endforeach;?><?php if(!$all):?><tr><td colspan="3" class="text-center text-muted">Belum ada usage log.</td></tr><?php endif;?></tbody></table></section>
<?php require __DIR__.'/../includes/footer.php';?>
